defense.secure_config:
// php.ini
open_basedir = /var/www/html

// Secure path check
$base = realpath('/var/www/html/media');
$requested = realpath('/var/www/html/media/' . $_GET['path']);
if (strpos($requested, $base) !== 0) { http_response_code(403); exit; }
